example:
composition "Curve" { ample 1  tempo 96  master-seed 17 }

midi-clip phrase {
  chords C Am F G
  bars 4
}

synth source {
  wave triangle
  gain -9 dB
  from phrase.notes -> notes
}

curve swell {
  value auto(1:0, 5:1000)
}

volume fadeIn {
  gain -30 dB + 30 dB * swell.level
  from source.audio -> audio
}

master output {
  from fadeIn.audio -> audio
}
